import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CardFooter
} from "@/components/ui/card";
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from "@/components/ui/carousel";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import type { Attraction } from "@/lib/types";
import Image from "next/image";
import { Button } from "../ui/button";
import { MapPin, ChevronsUpDown } from "lucide-react";
import { StarRating } from "../common/StarRating";
import { Reviews } from "./Reviews";
import { PlaceHolderImages } from "@/lib/placeholder-images";

type AttractionCardProps = {
  attraction: Attraction;
};

export function AttractionCard({ attraction }: AttractionCardProps) {
  const averageRating =
    attraction.reviews.length > 0
      ? attraction.reviews.reduce((acc, review) => acc + review.rating, 0) /
        attraction.reviews.length
      : 0;

  const attractionImages = attraction.images
    .map(id => PlaceHolderImages.find(img => img.id === id))
    .filter(Boolean);

  return (
    <Card className="flex flex-col h-full overflow-hidden shadow-lg hover:shadow-xl transition-shadow duration-300">
      <CardHeader className="p-0">
        <Carousel className="w-full">
          <CarouselContent>
            {attractionImages.length > 0 ? (
              attractionImages.map((image, index) => (
                <CarouselItem key={index}>
                  <div className="aspect-[4/3] relative bg-muted">
                    <Image
                      src={image!.imageUrl}
                      alt={image!.description}
                      fill
                      className="object-cover"
                      data-ai-hint={image!.imageHint}
                    />
                  </div>
                </CarouselItem>
              ))
            ) : (
              <CarouselItem>
                 <div className="aspect-[4/3] relative bg-muted">
                    <Image
                      src="https://picsum.photos/seed/placeholder/400/300"
                      alt="Placeholder image"
                      fill
                      className="object-cover"
                    />
                  </div>
              </CarouselItem>
            )}
          </CarouselContent>
          {attractionImages.length > 1 && (
            <>
              <CarouselPrevious className="absolute left-4" />
              <CarouselNext className="absolute right-4" />
            </>
          )}
        </Carousel>
      </CardHeader>
      <CardContent className="p-6 flex-grow">
        <CardTitle className="font-headline text-2xl mb-2">{attraction.name}</CardTitle>
        <div className="flex items-center gap-2 mb-4 text-muted-foreground">
          {averageRating > 0 && <StarRating rating={averageRating} />}
          <span className="text-sm">({attraction.reviews.length} review{attraction.reviews.length !== 1 ? 's' : ''})</span>
        </div>
        <CardDescription>{attraction.description}</CardDescription>
      </CardContent>
      <CardFooter className="p-6 pt-0 flex-col items-stretch gap-4">
        <Button asChild variant="secondary">
          <a
            href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(attraction.name)}`}
            target="_blank"
            rel="noopener noreferrer"
          >
            <MapPin className="mr-2 h-4 w-4" /> View on Map
          </a>
        </Button>
        <Collapsible>
          <CollapsibleTrigger asChild>
            <Button variant="outline" className="w-full">
              <ChevronsUpDown className="mr-2 h-4 w-4" /> Show Reviews
            </Button>
          </CollapsibleTrigger>
          <CollapsibleContent>
            <Reviews attraction={attraction} />
          </CollapsibleContent>
        </Collapsible>
      </CardFooter>
    </Card>
  );
}
