'use client';

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import type { Attraction } from "@/lib/types";
import { AttractionCard } from "./AttractionCard";
import { Building, Droplets, Castle, Trees, Landmark } from "lucide-react";

type AttractionsTabsProps = {
  attractions: Attraction[];
};

const categories = [
  { name: 'Museum', icon: Building },
  { name: 'Waterfall', icon: Droplets },
  { name: 'Fort', icon: Castle },
  { name: 'Park', icon: Trees },
  { name: 'Temple', icon: Landmark },
] as const;


export function AttractionsTabs({ attractions }: AttractionsTabsProps) {

  const attractionsByCategory = (category: Attraction['category']) => 
    attractions.filter(attraction => attraction.category === category);

  const availableCategories = categories.filter(cat => attractionsByCategory(cat.name).length > 0);
  
  if (attractions.length === 0) {
    return (
      <div className="text-center py-16">
        <h2 className="text-2xl font-semibold text-muted-foreground">No attractions found for this city yet.</h2>
        <p className="mt-2 text-muted-foreground">Check back later for updates!</p>
      </div>
    )
  }

  return (
    <Tabs defaultValue={availableCategories[0]?.name} className="w-full">
      <TabsList className="grid w-full grid-cols-2 sm:grid-cols-3 md:grid-cols-5 mb-8">
        {availableCategories.map(({ name, icon: Icon }) => (
            <TabsTrigger key={name} value={name}>
              <Icon className="mr-2 h-5 w-5" />
              {name}
            </TabsTrigger>
        ))}
      </TabsList>

      {availableCategories.map(({ name }) => (
        <TabsContent key={name} value={name}>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {attractionsByCategory(name).map((attraction) => (
              <AttractionCard key={attraction.id} attraction={attraction} />
            ))}
          </div>
        </TabsContent>
      ))}
    </Tabs>
  );
}
